function getChipClass(chipClass: 'bk' | 'ng' | 'cd') {
  switch (chipClass) {
    case 'bk':
      return styles.payChipBk;
    case 'ng':
      return styles.payChipNg;
    case 'cd':
      return styles.payChipCd;
    default:
      return '';
  }
}

export default function BdMap() {
  const [activeCity, setActiveCity] = useState<BangladeshCityPinData | null>(null);
  const tipTimerRef = useRef<NodeJS.Timeout | null>(null);

  const clearTipTimer = useCallback(() => {
    if (tipTimerRef.current) {
      clearTimeout(tipTimerRef.current);
      tipTimerRef.current = null;
    }
  }, []);

  const handleSelectCity = useCallback(
    (pin: BangladeshCityPinData) => {
      clearTipTimer();
      // On mobile tap or desktop click, replace currently open tooltip immediately
      setActiveCity(pin);

      // Auto-hide after 2800ms
      tipTimerRef.current = setTimeout(() => {
        setActiveCity(null);
      }, 2800);
    },
    [clearTipTimer]
  );

  const handleHoverCity = useCallback(
    (pin: BangladeshCityPinData) => {
      clearTipTimer();
      setActiveCity(pin);
    },
    [clearTipTimer]
  );

  const handleLeaveMap = useCallback(() => {
    clearTipTimer();
    tipTimerRef.current = setTimeout(() => {
      setActiveCity(null);
    }, 1200);
  }, [clearTipTimer]);

  useEffect(() => {
    return () => {
      clearTipTimer();
    };
  }, [clearTipTimer]);

  const tooltipText = activeCity
    ? `📍 ${activeCity.name} — ${activeCity.tagline}`
    : '📍 Click a city pin';

  return (
    <div className={styles.mapCard}>
      {/* Top bar */}
      <div className={styles.mapCardTop}>
        <div className={styles.mapSearchBar}>
          <FaMagnifyingGlass className={styles.mapSearchIcon} aria-hidden="true" />
          <span className={styles.mapSearchText}>Bangladesh</span>
        </div>
        <div className={styles.mapLiveWrap}>
          <div className={styles.mapDotLive} aria-hidden="true" />
          <span>Live</span>
        </div>
      </div>

      {/* Map body */}
      <div
        className={styles.mapBody}
        onMouseLeave={handleLeaveMap}
        onClick={(e) => {
          if (e.target === e.currentTarget) {
            setActiveCity(null);
          }
        }}
      >
        <div className={styles.bdSvgWrap}>
          <svg
            viewBox="0 0 400 544"
            xmlns="http://www.w3.org/2000/svg"
            className={styles.bdSvg}
            role="img"
            aria-label="Map of Bangladesh with city pins"
            preserveAspectRatio="xMidYMid meet"
          >
            <defs>
              <linearGradient id="mapGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#d8e9fc" stopOpacity="1" />
                <stop offset="100%" stopColor="#b3d3fa" stopOpacity="1" />
              </linearGradient>
              <filter id="mapShadow" x="-20%" y="-20%" width="140%" height="140%">
                <feDropShadow
                  dx="0"
                  dy="4"
                  stdDeviation="6"
                  floodColor="rgba(47,133,243,0.28)"
                />
              </filter>
            </defs>

            {/* Bangladesh border + islands */}
            <path
              id="bdPath"
              d={BANGLADESH_PATH}
              fill="url(#mapGrad)"
              stroke="#7db2f6"
              strokeWidth="1.5"
              strokeLinejoin="round"
              filter="url(#mapShadow)"
            />

            {/* Rivers: Jamuna (Brahmaputra), Padma (Ganges), Teesta, Surma (Barak) */}
            {RIVERS.map((d, i) => (
              <path key={`river-${i}`} className={styles.river} d={d} />
            ))}
            {RIVERS_SM.map((d, i) => (
              <path key={`river-sm-${i}`} className={styles.riverSm} d={d} />
            ))}

            {/* City pins */}
            {bangladeshCities.map((pin) => {
              const isTeal = pin.colorVariant === 'teal';
              const pulseClass = isTeal ? styles.pinPulseTeal : styles.pinPulseBlue;
              const circleColor = isTeal ? '#00c49a' : '#2f85f3';

              return (
                <g
                  key={pin.id}
                  className={styles.pinGroup}
                  data-city={`${pin.name} — ${pin.tagline}`}
                  role="button"
                  tabIndex={0}
                  aria-label={`${pin.name} — ${pin.tagline}`}
                  onClick={() => handleSelectCity(pin)}
                  onMouseEnter={() => handleHoverCity(pin)}
                  onFocus={() => handleHoverCity(pin)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      handleSelectCity(pin);
                    }
                  }}
                >
                  {/* Pulse circle */}
                  <circle
                    className={`${styles.pinPulse} ${pulseClass}`}
                    cx={pin.cx}
                    cy={pin.cy}
                    r={pin.pulseRadius}
                    style={{ animationDelay: pin.pulseDelay }}
                    aria-hidden="true"
                  />

                  {/* Optional outer ring (Dhaka) */}
                  {pin.hasOuterRing && (
                    <circle
                      cx={pin.cx}
                      cy={pin.cy}
                      r={10.5}
                      fill="none"
                      stroke="rgba(47,133,243,.35)"
                      strokeWidth="1"
                      aria-hidden="true"
                    />
                  )}

                  {/* Pin main dot */}
                  <circle
                    className={styles.pinCircle}
                    cx={pin.cx}
                    cy={pin.cy}
                    r={pin.circleRadius}
                    fill={circleColor}
                  />

                  {/* Inner white center dot */}
                  <circle
                    cx={pin.cx}
                    cy={pin.cy}
                    r={pin.innerRadius}
                    fill="#fff"
                    aria-hidden="true"
                  />

                  {/* Label text */}
                  <text
                    className={styles.pinLabel}
                    x={pin.labelX}
                    y={pin.labelY}
                    fontSize={pin.fontSize}
                    fontWeight={pin.fontWeight}
                    textAnchor={pin.anchor}
                  >
                    {pin.name}
                  </text>

                  {/* Invisible 44px hit-target circle for touch & mobile usability */}
                  <circle
                    cx={pin.cx}
                    cy={pin.cy}
                    r={22}
                    fill="transparent"
                    pointerEvents="all"
                    aria-hidden="true"
                  />
                </g>
              );
            })}

            {/* Coverage caption */}
            <text
              x="200"
              y="539"
              textAnchor="middle"
              fontSize="9.5"
              fill="#2f85f3"
              fontWeight="700"
              opacity=".85"
            >
              All Across Bangladesh
            </text>
          </svg>
        </div>

        {/* Tooltip */}
        <div
          id="mapTooltip"
          className={`${styles.mapTooltip} ${activeCity ? styles.mapTooltipShow : ''}`}
          role="status"
          aria-live="polite"
        >
          {tooltipText}
        </div>
      </div>

      {/* Footer */}
      <div className={styles.mapFooter}>
        <span className={styles.mapFooterLabel}>Payment Accepted</span>
        <div className={styles.payChips}>
          {paymentChips.map((chip) => (
            <div
              key={chip.id}
              className={`${styles.payChip} ${getChipClass(chip.chipClass)}`}
            >
              {chip.name}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
